import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"Class: DimensionChange","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: DimensionChange"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/client/classes/DimensionChange"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/client/classes/DimensionChange"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/client/src"}},"headers":[],"relativePath":"api/@jsprismarine/client/classes/DimensionChange.md","filePath":"api/@jsprismarine/client/classes/DimensionChange.md","lastUpdated":1794480539000}`),a={name:`api/@jsprismarine/client/classes/DimensionChange.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/client</a> / DimensionChange</p><h1 id="class-dimensionchange" tabindex="-1">Class: DimensionChange <a class="header-anchor" href="#class-dimensionchange" aria-label="Permalink to “Class: DimensionChange”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/0a689cdf4b69cc0ecba25fd1d0314da691dbd179/packages/client/src/DimensionChange.ts#L50" target="_blank" rel="noreferrer">client/src/DimensionChange.ts:50</a></p><p>The client&#39;s half of a dimension change.</p><p>A retail client shows a loading screen when <code>ChangeDimension</code> arrives and closes it once it has terrain to stand on, telling the server both edges through <code>ServerboundLoadingScreen</code>. The server holds the change open until it hears <code>EndLoadingScreen</code> with the id it handed out, so a client that never answers is a player stuck between worlds.</p><p>This one reports <code>StartLoadingScreen</code> as the change arrives and <code>EndLoadingScreen</code> after the first <code>LevelChunk</code> carrying the new dimension&#39;s id, with the client&#39;s own <code>PlayerAction ChangeDimensionAck</code> ahead of it as the retail client sends. Waiting for a chunk rather than answering at once keeps the server&#39;s chunk-first ordering honest: a server that announced the change and never sent terrain leaves this client on the screen too, which is the failure the retail client shows.</p><h2 id="extends" tabindex="-1">Extends <a class="header-anchor" href="#extends" aria-label="Permalink to “Extends”">​</a></h2><ul><li><code>EventEmitter</code></li></ul><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new DimensionChange</strong>(<code>session</code>, <code>runtimeEntityId</code>): <code>DimensionChange</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/0a689cdf4b69cc0ecba25fd1d0314da691dbd179/packages/client/src/DimensionChange.ts#L58" target="_blank" rel="noreferrer">client/src/DimensionChange.ts:58</a></p><p>Registers the two handlers on the session, for the life of the session.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="session" tabindex="-1">session <a class="header-anchor" href="#session" aria-label="Permalink to “session”">​</a></h5><p><a href="./ClientSession.html"><code>ClientSession</code></a></p><p>The session whose dimension changes this answers.</p><h5 id="runtimeentityid" tabindex="-1">runtimeEntityId <a class="header-anchor" href="#runtimeentityid" aria-label="Permalink to “runtimeEntityId”">​</a></h5><p>() =&gt; <code>bigint</code></p><p>Returns the runtime id <code>StartGame</code> assigned, for the ack.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>DimensionChange</code></p><h4 id="overrides" tabindex="-1">Overrides <a class="header-anchor" href="#overrides" aria-label="Permalink to “Overrides”">​</a></h4><p><code>EventEmitter.constructor</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="getpending" tabindex="-1">getPending() <a class="header-anchor" href="#getpending" aria-label="Permalink to “getPending()”">​</a></h3><blockquote><p><strong>getPending</strong>(): <a href="./../#pendingdimensionchange"><code>PendingDimensionChange</code></a> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/0a689cdf4b69cc0ecba25fd1d0314da691dbd179/packages/client/src/DimensionChange.ts#L68" target="_blank" rel="noreferrer">client/src/DimensionChange.ts:68</a></p><p>The change in progress, or null when this client is settled in a dimension.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#pendingdimensionchange"><code>PendingDimensionChange</code></a> | <code>null</code></p>`,31)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};